command:
set -eu
install -d -m 0755 /var/www/inventory
cat > /var/www/inventory/index.html <<EOF
<!doctype html>
<html lang="en">
<head><meta charset="utf-8"><title>Inventory</title></head>
<body>
<h1>Inventory Web Application</h1>
<p>Served by node2</p>
<table border="1">
<thead><tr><th>SKU</th><th>Item</th><th>Quantity</th></tr></thead>
<tbody>
<tr><td>INV-001</td><td>Keyboard</td><td>24</td></tr>
<tr><td>INV-002</td><td>Monitor</td><td>12</td></tr>
<tr><td>INV-003</td><td>Mouse</td><td>40</td></tr>
</tbody>
</table>
</body>
</html>
EOF
cat > /etc/nginx/http.d/default.conf <<EOF
server {
    listen 8080;
    listen [::]:8080;
    server_name _;
    root /var/www/inventory;
    index index.html;
    add_header X-Backend node2 always;

    location = /health {
        default_type text/plain;
        return 200 "healthy node2\n";
    }

    location / {
        try_files \$uri \$uri/ /index.html;
    }
}
EOF
nginx -t
rc-service nginx restart
rc-service nginx status
wget -qSO- -O- http://"$NODE_IP":8080/health 2>&1

