set -eu
cat > /etc/nginx/http.d/default.conf <<'EOF'
upstream inventory_backends {
    server 10.100.183.11:8080 max_fails=2 fail_timeout=5s;
    server 10.100.183.12:8080 max_fails=2 fail_timeout=5s;
    keepalive 16;
}

server {
    listen 80;
    listen [::]:80;
    server_name _;

    location = /lb-health {
        default_type text/plain;
        return 200 "load balancer healthy\n";
    }

    location / {
        proxy_http_version 1.1;
        proxy_set_header Connection "";
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_pass http://inventory_backends;
        add_header X-Load-Balancer node1 always;
    }
}
EOF
nginx -t
rc-service nginx restart
rc-service nginx status
wget -qSO- -O- http://"$NODE_IP"/lb-health 2>&1

